insert into public.exercises (slug, name, description, muscle_groups, equipment, type, difficulty, unilateral, video_path, thumb_path) values
  ('sentadilla', 'Sentadilla', 'Pies a la anchura de los hombros. Baja llevando la cadera atrás como si te sentaras, con la espalda recta, y sube empujando el suelo.', array['piernas', 'gluteos']::text[], array['ninguno']::text[], 'fuerza', 1, false, 'videos/sentadilla.mp4', 'thumbs/sentadilla.webp'),
  ('zancada', 'Zancada', 'Da un paso al frente y baja hasta que ambas rodillas formen 90°. La rodilla delantera no pasa de la punta del pie. Vuelve y cambia de pierna.', array['piernas', 'gluteos']::text[], array['ninguno']::text[], 'fuerza', 1, true, 'videos/zancada.mp4', 'thumbs/zancada.webp'),
  ('sentadilla_salto', 'Sentadilla con salto', 'Baja a sentadilla y salta con fuerza estirando todo el cuerpo. Aterriza suave flexionando las rodillas.', array['piernas', 'gluteos']::text[], array['ninguno']::text[], 'cardio', 2, false, 'videos/sentadilla_salto.mp4', 'thumbs/sentadilla_salto.webp'),
  ('elevacion_talones', 'Elevación de talones', 'De pie, sube sobre las puntas de los pies apretando los gemelos y baja despacio.', array['gemelos']::text[], array['ninguno']::text[], 'fuerza', 1, false, 'videos/elevacion_talones.mp4', 'thumbs/elevacion_talones.webp'),
  ('flexiones', 'Flexiones', 'Manos bajo los hombros y cuerpo recto de cabeza a talones. Baja el pecho hacia el suelo y empuja para subir.', array['pecho', 'triceps', 'hombros']::text[], array['ninguno']::text[], 'fuerza', 2, false, 'videos/flexiones.mp4', 'thumbs/flexiones.webp'),
  ('flexiones_rodillas', 'Flexiones con rodillas', 'Como una flexión, pero con las rodillas apoyadas. Mantén la cadera alineada con el tronco.', array['pecho', 'triceps']::text[], array['ninguno']::text[], 'fuerza', 1, false, 'videos/flexiones_rodillas.mp4', 'thumbs/flexiones_rodillas.webp'),
  ('pike_pushup', 'Flexión pica', 'Cadera arriba formando una V invertida. Flexiona los codos llevando la cabeza hacia el suelo, delante de las manos.', array['hombros', 'triceps']::text[], array['ninguno']::text[], 'fuerza', 3, false, 'videos/pike_pushup.mp4', 'thumbs/pike_pushup.webp'),
  ('puente_gluteo', 'Puente de glúteo', 'Tumbado boca arriba con las rodillas flexionadas. Sube la cadera apretando los glúteos y baja controlando.', array['gluteos', 'isquios']::text[], array['ninguno']::text[], 'fuerza', 1, false, 'videos/puente_gluteo.mp4', 'thumbs/puente_gluteo.webp'),
  ('plancha', 'Plancha', 'Apoya antebrazos y puntas de los pies. Cuerpo recto, abdomen y glúteos apretados. Respira y aguanta.', array['core', 'hombros']::text[], array['ninguno']::text[], 'core', 1, false, 'videos/plancha.mp4', 'thumbs/plancha.webp'),
  ('plancha_lateral', 'Plancha lateral', 'De lado, apoya el antebrazo bajo el hombro y eleva la cadera hasta alinear el cuerpo. Baja y sube la cadera despacio.', array['oblicuos', 'core']::text[], array['ninguno']::text[], 'core', 2, true, 'videos/plancha_lateral.mp4', 'thumbs/plancha_lateral.webp'),
  ('crunch', 'Crunch abdominal', 'Tumbado con rodillas flexionadas y manos tras la cabeza. Despega los hombros del suelo contrayendo el abdomen, sin tirar del cuello.', array['abdominales', 'core']::text[], array['ninguno']::text[], 'core', 1, false, 'videos/crunch.mp4', 'thumbs/crunch.webp'),
  ('bicicleta', 'Bicicleta abdominal', 'Boca arriba con los hombros despegados. Lleva una rodilla al pecho mientras estiras la otra pierna, alternando como si pedalearas.', array['oblicuos', 'abdominales']::text[], array['ninguno']::text[], 'core', 2, false, 'videos/bicicleta.mp4', 'thumbs/bicicleta.webp'),
  ('dead_bug', 'Bicho muerto', 'Boca arriba, brazos al techo y rodillas a 90°. Estira un brazo hacia atrás y la pierna contraria hacia delante sin despegar la zona lumbar.', array['core', 'abdominales']::text[], array['ninguno']::text[], 'core', 1, false, 'videos/dead_bug.mp4', 'thumbs/dead_bug.webp'),
  ('bird_dog', 'Bird dog', 'A cuatro patas, estira un brazo al frente y la pierna contraria atrás, manteniendo la espalda plana. Alterna lados.', array['lumbar', 'core', 'gluteos']::text[], array['ninguno']::text[], 'core', 1, false, 'videos/bird_dog.mp4', 'thumbs/bird_dog.webp'),
  ('superman', 'Superman', 'Tumbado boca abajo con brazos estirados al frente. Eleva a la vez brazos, pecho y piernas, aguanta un instante y baja.', array['lumbar', 'gluteos']::text[], array['ninguno']::text[], 'core', 1, false, 'videos/superman.mp4', 'thumbs/superman.webp'),
  ('jumping_jacks', 'Jumping jacks', 'Salta abriendo piernas y subiendo los brazos por encima de la cabeza; vuelve a cerrar con otro salto. Ritmo constante.', array['cardio', 'cuerpo_completo']::text[], array['ninguno']::text[], 'cardio', 1, false, 'videos/jumping_jacks.mp4', 'thumbs/jumping_jacks.webp'),
  ('mountain_climbers', 'Escaladores', 'En plancha alta, lleva las rodillas al pecho alternando rápido, como si corrieras sin despegar las manos del suelo.', array['cardio', 'core']::text[], array['ninguno']::text[], 'cardio', 2, false, 'videos/mountain_climbers.mp4', 'thumbs/mountain_climbers.webp'),
  ('burpee', 'Burpee', 'Agáchate, apoya las manos, lanza los pies atrás a plancha, recógelos y salta con los brazos arriba.', array['cardio', 'cuerpo_completo']::text[], array['ninguno']::text[], 'cardio', 3, false, 'videos/burpee.mp4', 'thumbs/burpee.webp'),
  ('rodillas_al_pecho', 'Rodillas arriba', 'Corre en el sitio subiendo las rodillas a la altura de la cadera y moviendo los brazos.', array['cardio', 'piernas']::text[], array['ninguno']::text[], 'cardio', 1, false, 'videos/rodillas_al_pecho.mp4', 'thumbs/rodillas_al_pecho.webp'),
  ('skater', 'Saltos de patinador', 'Salta lateralmente de una pierna a la otra, cruzando la pierna libre por detrás y balanceando los brazos.', array['cardio', 'piernas', 'gluteos']::text[], array['ninguno']::text[], 'cardio', 2, false, 'videos/skater.mp4', 'thumbs/skater.webp'),
  ('boxeo_sombra', 'Boxeo de sombra', 'En guardia, con las rodillas algo flexionadas, lanza golpes rectos alternando brazos y vuelve rápido a la guardia.', array['cardio', 'hombros', 'brazos']::text[], array['ninguno']::text[], 'cardio', 1, false, 'videos/boxeo_sombra.mp4', 'thumbs/boxeo_sombra.webp'),
  ('gato_camello', 'Gato-camello', 'A cuatro patas, redondea la espalda hacia el techo metiendo la barbilla y luego húndela mirando al frente. Movimiento lento.', array['espalda', 'lumbar']::text[], array['ninguno']::text[], 'movilidad', 1, false, 'videos/gato_camello.mp4', 'thumbs/gato_camello.webp'),
  ('estiramiento_isquios', 'Estiramiento de isquios', 'De pie, inclina el tronco hacia delante con la espalda larga y deja caer los brazos hacia los pies. Respira y suelta.', array['isquios', 'lumbar']::text[], array['ninguno']::text[], 'movilidad', 1, false, 'videos/estiramiento_isquios.mp4', 'thumbs/estiramiento_isquios.webp'),
  ('circulos_brazos', 'Círculos de brazos', 'De pie, dibuja círculos amplios con los brazos estirados para movilizar los hombros.', array['hombros']::text[], array['ninguno']::text[], 'movilidad', 1, false, 'videos/circulos_brazos.mp4', 'thumbs/circulos_brazos.webp'),
  ('estocada_flexor', 'Estiramiento de flexor de cadera', 'Rodilla trasera en el suelo y pie delantero apoyado. Lleva la cadera suavemente hacia delante manteniendo el tronco erguido.', array['piernas', 'gluteos']::text[], array['ninguno']::text[], 'movilidad', 1, true, 'videos/estocada_flexor.mp4', 'thumbs/estocada_flexor.webp'),
  ('postura_nino', 'Postura del niño', 'De rodillas, siéntate sobre los talones e inclina el tronco hacia delante estirando los brazos en el suelo. Respira hondo.', array['espalda', 'lumbar']::text[], array['ninguno']::text[], 'movilidad', 1, false, 'videos/postura_nino.mp4', 'thumbs/postura_nino.webp'),
  ('fondos_silla', 'Fondos de tríceps en silla', 'Manos en el borde de la silla detrás de ti. Baja flexionando los codos hacia atrás y sube estirando los brazos.', array['triceps', 'hombros']::text[], array['silla']::text[], 'fuerza', 2, false, 'videos/fondos_silla.mp4', 'thumbs/fondos_silla.webp'),
  ('sentadilla_bulgara', 'Sentadilla búlgara', 'Apoya el empeine del pie trasero en una silla. Baja la rodilla trasera hacia el suelo con el tronco firme y sube con la pierna delantera.', array['piernas', 'gluteos']::text[], array['silla']::text[], 'fuerza', 3, true, 'videos/sentadilla_bulgara.mp4', 'thumbs/sentadilla_bulgara.webp'),
  ('flexiones_inclinadas', 'Flexiones inclinadas en silla', 'Manos en el asiento de una silla estable y cuerpo recto. Baja el pecho hacia el borde y empuja. Más fácil que en el suelo.', array['pecho', 'triceps']::text[], array['silla']::text[], 'fuerza', 1, false, 'videos/flexiones_inclinadas.mp4', 'thumbs/flexiones_inclinadas.webp'),
  ('flexiones_declinadas', 'Flexiones declinadas', 'Pies sobre una silla y manos en el suelo. Cuerpo recto; baja el pecho y empuja. Trabaja más el pecho alto y los hombros.', array['pecho', 'hombros', 'triceps']::text[], array['silla']::text[], 'fuerza', 3, false, 'videos/flexiones_declinadas.mp4', 'thumbs/flexiones_declinadas.webp'),
  ('sentadilla_silla', 'Sentarse y levantarse de la silla', 'Siéntate en la silla de forma controlada y levántate sin impulso, empujando con las piernas.', array['piernas', 'gluteos']::text[], array['silla']::text[], 'fuerza', 1, false, 'videos/sentadilla_silla.mp4', 'thumbs/sentadilla_silla.webp'),
  ('sentadilla_pared', 'Sentadilla isométrica en pared', 'Espalda apoyada en la pared y rodillas a 90°, como sentado en una silla invisible. Aguanta respirando.', array['cuadriceps', 'gluteos']::text[], array['pared']::text[], 'fuerza', 2, false, 'videos/sentadilla_pared.mp4', 'thumbs/sentadilla_pared.webp'),
  ('flexiones_pared', 'Flexiones en pared', 'De pie frente a la pared, manos a la altura del pecho. Inclínate hacia la pared flexionando los codos y empuja para volver.', array['pecho', 'triceps']::text[], array['pared']::text[], 'fuerza', 1, false, 'videos/flexiones_pared.mp4', 'thumbs/flexiones_pared.webp'),
  ('step_up', 'Subida al escalón', 'Sube a un escalón o banco estable empujando con la pierna de arriba y eleva la rodilla contraria. Baja controlando.', array['piernas', 'gluteos']::text[], array['escalon']::text[], 'fuerza', 1, true, 'videos/step_up.mp4', 'thumbs/step_up.webp'),
  ('elevacion_talones_escalon', 'Elevación de talones en escalón', 'Con la parte delantera de los pies en el borde de un escalón, deja bajar los talones y sube todo lo que puedas.', array['gemelos']::text[], array['escalon']::text[], 'fuerza', 2, false, 'videos/elevacion_talones_escalon.mp4', 'thumbs/elevacion_talones_escalon.webp'),
  ('hip_thrust_sofa', 'Hip thrust en sofá', 'Apoya la parte alta de la espalda en el borde del sofá, pies en el suelo. Sube la cadera hasta alinear tronco y muslos y aprieta glúteos.', array['gluteos', 'isquios']::text[], array['sofa']::text[], 'fuerza', 2, false, 'videos/hip_thrust_sofa.mp4', 'thumbs/hip_thrust_sofa.webp'),
  ('escaladores_toalla', 'Escaladores deslizantes con toalla', 'En plancha alta con los pies sobre una toalla en suelo liso. Desliza las rodillas al pecho alternando, sin levantar los pies.', array['core', 'cardio']::text[], array['toalla']::text[], 'cardio', 2, false, 'videos/escaladores_toalla.mp4', 'thumbs/escaladores_toalla.webp'),
  ('good_morning_mochila', 'Buenos días con mochila', 'Mochila cargada a la espalda y manos tras la cabeza. Inclina el tronco llevando la cadera atrás con la espalda recta y vuelve.', array['isquios', 'lumbar', 'gluteos']::text[], array['mochila']::text[], 'fuerza', 2, false, 'videos/good_morning_mochila.mp4', 'thumbs/good_morning_mochila.webp'),
  ('remo_mochila', 'Remo con mochila', 'Inclina el tronco con la espalda recta sujetando la mochila. Llévala hacia el abdomen juntando las escápulas y baja despacio.', array['espalda', 'biceps']::text[], array['mochila']::text[], 'fuerza', 1, false, 'videos/remo_mochila.mp4', 'thumbs/remo_mochila.webp'),
  ('curl_botellas', 'Curl de bíceps con botellas', 'De pie con una botella en cada mano y codos pegados al cuerpo. Flexiona los codos subiendo las botellas y baja controlando.', array['biceps']::text[], array['botellas']::text[], 'fuerza', 1, false, 'videos/curl_botellas.mp4', 'thumbs/curl_botellas.webp'),
  ('elevaciones_laterales_botellas', 'Elevaciones laterales con botellas', 'De pie, sube los brazos hacia los lados hasta la altura de los hombros con los codos ligeramente flexionados.', array['hombros']::text[], array['botellas']::text[], 'fuerza', 1, false, 'videos/elevaciones_laterales_botellas.mp4', 'thumbs/elevaciones_laterales_botellas.webp'),
  ('remo_goma', 'Remo sentado con goma', 'Sentado con las piernas estiradas y la goma en los pies. Tira de ella llevando los codos atrás y juntando las escápulas.', array['espalda', 'biceps']::text[], array['gomas']::text[], 'fuerza', 1, false, 'videos/remo_goma.mp4', 'thumbs/remo_goma.webp'),
  ('press_pecho_goma', 'Press de pecho con goma', 'Pasa la goma por la espalda a la altura de las axilas y empuja con ambas manos al frente hasta estirar los brazos.', array['pecho', 'triceps']::text[], array['gomas']::text[], 'fuerza', 1, false, 'videos/press_pecho_goma.mp4', 'thumbs/press_pecho_goma.webp'),
  ('face_pull_goma', 'Face pull con goma', 'Goma anclada a la altura de la cara. Tira hacia tu frente separando las manos y con los codos altos.', array['hombros', 'espalda']::text[], array['gomas']::text[], 'fuerza', 2, false, 'videos/face_pull_goma.mp4', 'thumbs/face_pull_goma.webp'),
  ('pull_apart_goma', 'Aperturas con goma', 'Brazos al frente sujetando la goma. Ábrelos hacia los lados estirando la goma hasta formar una T y vuelve despacio.', array['espalda', 'hombros']::text[], array['gomas']::text[], 'fuerza', 1, false, 'videos/pull_apart_goma.mp4', 'thumbs/pull_apart_goma.webp'),
  ('curl_goma', 'Curl de bíceps con goma', 'Pisa la goma y sujeta los extremos. Flexiona los codos sin moverlos del costado y baja controlando la tensión.', array['biceps']::text[], array['gomas']::text[], 'fuerza', 1, false, 'videos/curl_goma.mp4', 'thumbs/curl_goma.webp'),
  ('extension_triceps_goma', 'Extensión de tríceps con goma', 'Pisa la goma con el pie de atrás y sujétala detrás de la cabeza. Estira los brazos hacia el techo y baja doblando los codos.', array['triceps']::text[], array['gomas']::text[], 'fuerza', 2, false, 'videos/extension_triceps_goma.mp4', 'thumbs/extension_triceps_goma.webp'),
  ('sentadilla_goma', 'Sentadilla con goma', 'Pisa la goma y sujétala a la altura de los hombros. Haz una sentadilla profunda manteniendo la tensión.', array['piernas', 'gluteos']::text[], array['gomas']::text[], 'fuerza', 2, false, 'videos/sentadilla_goma.mp4', 'thumbs/sentadilla_goma.webp'),
  ('patada_gluteo_goma', 'Patada de glúteo con goma', 'A cuatro patas con la goma entre la mano y el pie. Empuja la pierna hacia atrás y arriba apretando el glúteo, sin arquear la espalda.', array['gluteos']::text[], array['gomas']::text[], 'fuerza', 1, true, 'videos/patada_gluteo_goma.mp4', 'thumbs/patada_gluteo_goma.webp'),
  ('monster_walk_goma', 'Pasos laterales con goma', 'Goma alrededor de las rodillas y semisentadilla. Da pasos laterales cortos manteniendo la tensión y las rodillas hacia fuera.', array['gluteos', 'aductores']::text[], array['gomas']::text[], 'fuerza', 1, false, 'videos/monster_walk_goma.mp4', 'thumbs/monster_walk_goma.webp'),
  ('goblet_squat', 'Sentadilla goblet', 'Sujeta la mancuerna vertical junto al pecho. Baja a sentadilla con los codos entre las rodillas y sube empujando con los talones.', array['piernas', 'gluteos']::text[], array['mancuerna']::text[], 'fuerza', 2, false, 'videos/goblet_squat.mp4', 'thumbs/goblet_squat.webp'),
  ('peso_muerto_rumano', 'Peso muerto rumano', 'Mancuerna en las manos frente a los muslos. Lleva la cadera atrás bajando el peso pegado a las piernas, espalda recta, y sube apretando glúteos.', array['isquios', 'gluteos', 'lumbar']::text[], array['mancuerna']::text[], 'fuerza', 2, false, 'videos/peso_muerto_rumano.mp4', 'thumbs/peso_muerto_rumano.webp'),
  ('remo_mancuerna', 'Remo a una mano', 'Pie atrás, mano libre apoyada en la rodilla delantera y espalda recta. Tira de la mancuerna hacia la cadera con el codo pegado.', array['espalda', 'biceps']::text[], array['mancuerna']::text[], 'fuerza', 2, true, 'videos/remo_mancuerna.mp4', 'thumbs/remo_mancuerna.webp'),
  ('press_hombro_mancuerna', 'Press de hombro a una mano', 'De pie, mancuerna a la altura del hombro. Empújala hacia el techo hasta estirar el brazo sin arquear la espalda y baja controlando.', array['hombros', 'triceps']::text[], array['mancuerna']::text[], 'fuerza', 2, true, 'videos/press_hombro_mancuerna.mp4', 'thumbs/press_hombro_mancuerna.webp'),
  ('swing_mancuerna', 'Swing con mancuerna', 'Sujeta la mancuerna con ambas manos. Lleva la cadera atrás y proyéctala adelante con fuerza para balancear el peso hasta el pecho.', array['gluteos', 'isquios', 'cardio']::text[], array['mancuerna']::text[], 'cardio', 2, false, 'videos/swing_mancuerna.mp4', 'thumbs/swing_mancuerna.webp'),
  ('thruster_mancuerna', 'Thruster con mancuerna', 'Mancuerna a la altura del pecho. Haz una sentadilla y, al subir, empuja el peso por encima de la cabeza en un solo movimiento.', array['cuerpo_completo', 'piernas', 'hombros']::text[], array['mancuerna']::text[], 'fuerza', 3, false, 'videos/thruster_mancuerna.mp4', 'thumbs/thruster_mancuerna.webp'),
  ('zancada_mancuerna', 'Zancada con mancuerna', 'Mancuerna vertical junto al pecho. Da un paso al frente y baja hasta 90° en ambas rodillas; vuelve empujando con la pierna delantera.', array['piernas', 'gluteos']::text[], array['mancuerna']::text[], 'fuerza', 2, true, 'videos/zancada_mancuerna.mp4', 'thumbs/zancada_mancuerna.webp'),
  ('hollow_hold', 'Hollow hold', 'Boca arriba, despega hombros y piernas del suelo con los brazos estirados atrás. Lumbar pegada a la esterilla. Aguanta.', array['abdominales', 'core']::text[], array['esterilla']::text[], 'core', 3, false, 'videos/hollow_hold.mp4', 'thumbs/hollow_hold.webp'),
  ('v_up', 'V-up', 'Tumbado con brazos estirados atrás. Sube a la vez tronco y piernas rectas intentando tocar los pies con las manos y baja controlando.', array['abdominales', 'core']::text[], array['esterilla']::text[], 'core', 3, false, 'videos/v_up.mp4', 'thumbs/v_up.webp'),
  ('foam_cuadriceps', 'Foam roller de cuádriceps', 'Boca abajo apoyado en antebrazos con el rodillo bajo los muslos. Rueda despacio desde la cadera hasta encima de la rodilla.', array['cuadriceps']::text[], array['foam']::text[], 'recuperacion', 1, false, 'videos/foam_cuadriceps.mp4', 'thumbs/foam_cuadriceps.webp'),
  ('foam_isquios', 'Foam roller de isquiotibiales', 'Sentado con las manos detrás y el rodillo bajo los muslos. Eleva la cadera y rueda despacio desde el glúteo hasta la rodilla.', array['isquios']::text[], array['foam']::text[], 'recuperacion', 1, false, 'videos/foam_isquios.mp4', 'thumbs/foam_isquios.webp'),
  ('foam_gluteo', 'Foam roller de glúteo', 'Siéntate sobre el rodillo con las manos detrás y los pies en el suelo. Muévete adelante y atrás buscando las zonas cargadas.', array['gluteos']::text[], array['foam']::text[], 'recuperacion', 1, false, 'videos/foam_gluteo.mp4', 'thumbs/foam_gluteo.webp'),
  ('foam_espalda', 'Foam roller de espalda alta', 'Rodillo bajo la parte alta de la espalda, rodillas flexionadas y manos tras la cabeza. Rueda despacio entre los omóplatos.', array['espalda']::text[], array['foam']::text[], 'recuperacion', 1, false, 'videos/foam_espalda.mp4', 'thumbs/foam_espalda.webp'),
  ('foam_gemelos', 'Foam roller de gemelos', 'Sentado con las manos detrás y el rodillo bajo los gemelos. Levanta la cadera y rueda del tobillo a debajo de la rodilla.', array['gemelos']::text[], array['foam']::text[], 'recuperacion', 1, false, 'videos/foam_gemelos.mp4', 'thumbs/foam_gemelos.webp')
